pub fn test_prime(candidate: u64) -> bool {
    // By assumption, candidate > 1, but we still guard against 0 and 1:
    if candidate <= 1 {
        return false;
    }
    // Trial-divide by all f from 2 up to floor(sqrt(candidate)).
    // We avoid overflow in `f * f` by testing `f <= candidate / f` instead.
    let mut f: u64 = 2;
    while f <= candidate / f {
        if candidate % f == 0 {
            // Found a non‐trivial divisor ⇒ not prime
            return false;
        }
        f += 1;
    }
    // No divisors found ⇒ prime
    true
}

